// ------------------------------------------------------------ libraries
#include <Arduino.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>
#include <PCA95x5.h>
#include <Adafruit_NeoPixel.h>
#include <Anitracks_ADS7142.h>
#include <Arduino_LSM6DSOX.h>
#include <QMC5883LCompass.h>
#include <VL6180X.h>
#include <Servo.h>
#include <WiFiNINA.h>

#include "main.cpp"

// ----------------------------------------------------------------- pins
#define TFT_CS         4
#define TFT_DC         3
#define TFT_RST        17        // Arduino pin number
#define BUZZ_PIN       2
#define NEO_PIN        17        // RP2040 GPIO number - NOT Arduino pin 17
#define NEO_COUNT      18
#define SERVO_PIN      9
#define RIGHT_BUTTON   A0        // SW1, direct GPIO, active-LOW

// motor driver (Lab 8)
#define AIN1           0
#define AIN2           1
#define BIN1           8
#define BIN2           A2

// ---------------------------------------------------- vehicle constants
// Facts about this chassis, not policy. They belong here with the pin
// numbers because you cannot vote on them: they come from the track
// width, the wheel diameter and the gearing. Lab 8 derives them.
#define K_TRACK        1.6      // differential gain: how hard a commanded
                                // turn rate pulls the two wheels apart
#define PWM_MAX        255      // full scale of one motor channel

// --------------------------------------------------------- I2C addresses
#define ADDR_MUX       0x20      // U31 expander: buttons + enable lines
#define ADDR_LEDMUX    0x21      // U32 expander: 7-segment display
#define ADDR_TEMPPOT   0x18      // U37 ADC: ch0 = TEMP0, ch1 = POT
#define ADDR_LIGHT     0x1F      // U36 ADC: ch0 = LIGHT1, ch1 = LIGHT2
#define ADDR_COMPASS   0x0D      // QMC5883L
#define ADDR_RANGE     0x29      // VL6180X  (needs its enable line first)
#define ADDR_IMU       0x6A      // LSM6DSOX

// ---------------------------------------------------------- button masks
// Read from the U31 expander with muxU31.read().
#define MASK_SW1       0x0000    // not on the expander: direct GPIO, A0
#define MASK_SW2       0x0001    // active-LOW
#define MASK_FRONT     0x0002    // active-HIGH
#define MASK_BACK      0x0004    // active-HIGH

// -------------------------------------------------------------- hardware
Adafruit_ST7789   tft = Adafruit_ST7789(TFT_CS, TFT_DC, TFT_RST);
Adafruit_NeoPixel strip(NEO_COUNT, NEO_PIN, NEO_GRB + NEO_KHZ800);
PCA9535           muxU31;        // buttons and enable lines   (0x20)
PCA9535           ledmux;        // 7-segment display          (0x21)
ADS7142           adcTempPot(ADDR_TEMPPOT);
ADS7142           adcLight(ADDR_LIGHT);
QMC5883LCompass   compass;
VL6180X           rangefinder;
Servo             mast;

// 7-segment lookup tables, exactly as built in Lab 2
extern uint16_t SEG[];           // segment patterns, digits 0-9
extern uint16_t POS[];           // digit positions, POS[0] = rightmost

// -------------------------------------------------------------- roll call
// One row per device the checkout expects to find on the I2C bus.
// required == true  ->  the vehicle cannot be trusted without it
// required == false ->  a missing device is reported, not disqualifying
struct Device {
  byte        addr;
  const char* name;
  bool        required;
};

extern Device bus[];
extern int    busCount;
extern bool   busOK[];

// ----------------------------------------------------------------- report
// One row per test that was run. The health report is just this list,
// printed twice: once on the TFT, once down the serial link.
struct TestResult {
  const char* name;
  bool        passed;
};

extern TestResult results[];
extern int        testCount;

// ============================ DECLARATIONS ===========================
//  Every function in this tool, promised here, defined in myFunctions.ino
// =====================================================================

// --- startup and shutdown -------------------------------------------
void beginCheckout();                    // power up, roll call, log header
void endCheckout();                      // health report, CERTIFIED/GROUNDED

// --- roll call -------------------------------------------------------
void scanBus();                          // ask every expected address
void showRollCall();                     // draw the roll call on the TFT
bool requiredBusOK();                    // false if a required device is gone
bool present(byte addr);                 // did this address answer?
void sweepBus();                         // OPTIONAL: scan 0x08 - 0x77

// --- reporting -------------------------------------------------------
void addResult(const char* name, bool passed);
void showReport();

// --- operator helpers ------------------------------------------------
void prompt(const char* l1, const char* l2 = "", const char* l3 = "");
bool waitPress(uint16_t mask, bool activeHigh, unsigned long timeout);
bool askOperator(const char* question, const char* detail = "");

// --- the tests -------------------------------------------------------
// Each one answers exactly one question with exactly one bool.
// true = PASS, false = FAIL. Nothing else is allowed.
bool testBuzzer();      // Lab 1   two tones, operator confirms
bool testNeoPixels();   // Lab 5   ring lights red, green, blue
bool testButtons();     // Lab 3   four buttons, two polarities
bool test7Seg();        // Lab 2   four digits show 1 2 3 4
bool testPot();         // Lab 5   full travel of the throttle pot
bool testTemp();        // Lab 5   plausible room temp, and it responds
bool testLight();       // Lab 5   covered reading drops
bool testIMU();         // Lab 6   pitch changes sign
bool testCompass();     // Lab 6   azimuth moves on a half turn
bool testRange();       // Lab 8   hand at 100 mm
bool testServo();       // Lab 8   mast sweeps
bool testMotors();      // Lab 8   straight, then a spin -- PIT MODE ONLY
bool testWiFi();        // Lab 10  radio answers and hears a network

